import sys
from typing import List

MOD = 10**9 + 7

def power(x: int, y: int) -> int:
    if y == 0:
        return 1
    p = power(x, y // 2)
    p = (p * p) % MOD
    if y % 2 == 1:
        p = (p * x) % MOD
    return p

def factorial(n: int) -> int:
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % MOD
    return result

def mod_inverse(a: int, m: int) -> int:
    return power(a, m - 2)

def stirling_second_kind(n: int, k: int) -> int:
    if k == 0:
        return 0 if n > 0 else 1
    if n == 0:
        return 0 if k > 0 else 1
    s = [0] * (k + 1)
    s[0] = 1
    for i in range(1, n + 1):
        for j in range(k, 0, -1):
            s[j] = (s[j] + j * s[j - 1]) % MOD
    return s[k]

def sum_of_weights(n: int, k: int, weights: List[int]) -> int:
    total_weight = sum(weights)
    stirling = stirling_second_kind(n, k)
    factorial_k = factorial(k)
    inverse_factorial_k = mod_inverse(factorial_k, MOD)
    result = 0
    for i in range(k + 1):
        sign = (-1) ** (k - i)
        binom_coeff = stirling * mod_inverse(stirling_second_kind(i, k), MOD) % MOD
        result = (result + sign * binom_coeff * power(total_weight, i) * factorial_k * inverse_factorial_k) % MOD
    return result

